// Generated by vibelang from db/migrations/0100_todo_leaves.ts; the migrate flow writes it again with each batch.
import { Effect } from "effect";
import { SqlClient } from "effect/sql";
// TODO leaves (decision 0153, src/features/todos/leaves.ts): one row per TODO with an issue, the leaf's state and
// validation, readable by everyone who may read the repository's issues. It holds no title, prompt, acceptance criteria,
// SHA or person. `todo_id` has no foreign key, and `executor`, `proof_source` and `reported_at` hold their defaults until
// work outside the stack has leaves too.
//
// A deferred trigger on `todos` is the table's one writer. The deploy migrates before it replaces the Worker, and a
// rollback brings older Workers back, so a writer in the Worker's code would leave leaves missing or stale behind any
// Worker without it. The trigger runs under every writer of `todos`, at commit, when its transaction's `todo_requests` row
// exists too. It takes the leaf's own row lock, under the lock its transaction already holds on the TODO's row, and
// nothing shared: no advisory lock, no foreign key, no other row. It reads the TODO's final state, not the row that fired
// it, so a TODO deleted or unlinked by commit loses its leaf, and readers stop seeing it. It fires only when a column a
// leaf derives from is set, or the row is deleted, so a step or position change costs nothing.
//
// The backfill writes every existing TODO with an issue as `none`: it was never proven. Creating the trigger takes SHARE
// ROW EXCLUSIVE on `todos`, which holds every writer back until the migrations' one transaction ends, so the backfill
// misses none. A deploy that can't get that lock soon fails and is run again. Production had 45 such TODOs of 2,250 on
// 2026-11-03, so one statement is short.
export default Effect.gen(function* () {
    const sql = yield* SqlClient.SqlClient;
    yield* sql `SET LOCAL lock_timeout = '5s'`;
    yield* sql `
    CREATE TABLE todo_leaves (
      todo_id uuid PRIMARY KEY,
      repo_id text NOT NULL,
      number integer NOT NULL CHECK (number >= 1),
      issue_number integer NOT NULL CHECK (issue_number >= 1),
      state text NOT NULL,
      validation text NOT NULL
        CHECK (validation IN ('none', 'pending', 'passed', 'failed', 'stale', 'no_criteria')),
      pr_number integer,
      executor text NOT NULL DEFAULT 'smithers' CHECK (executor IN ('smithers', 'external')),
      proof_source text CHECK (proof_source IN ('smithers', 'lane')),
      reported_at timestamptz,
      updated_at timestamptz NOT NULL
    )`;
    yield* sql `CREATE INDEX todo_leaves_issue ON todo_leaves (repo_id, issue_number)`;
    yield* sql `ALTER TABLE todo_leaves REPLICA IDENTITY FULL`;
    // Named in the schema it is created in, with its own search_path, as github_repo_role_state is (migration 0096).
    yield* sql `
    DO $do$ BEGIN EXECUTE format($create$
      CREATE FUNCTION %1$I.todo_leaves_project() RETURNS trigger
      LANGUAGE plpgsql
      SET search_path = pg_catalog, pg_temp
      AS $fn$
      DECLARE
        todo uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;
      BEGIN
        IF NOT EXISTS (SELECT 1 FROM %1$I.todos t WHERE t.id = todo AND t.issue_number IS NOT NULL) THEN
          DELETE FROM %1$I.todo_leaves WHERE todo_id = todo;
          RETURN NULL;
        END IF;
        INSERT INTO %1$I.todo_leaves (todo_id, repo_id, number, issue_number, state, validation, pr_number, updated_at)
        SELECT t.id, t.repo_id, t.number, t.issue_number, t.state,
          CASE WHEN coalesce(cardinality(r.acceptance), 0) = 0 THEN 'no_criteria' ELSE 'pending' END,
          t.pr_number, t.updated_at
        FROM %1$I.todos t LEFT JOIN %1$I.todo_requests r ON r.todo_id = t.id AND r.revision = t.revision
        WHERE t.id = todo
        ON CONFLICT (todo_id) DO UPDATE SET issue_number = EXCLUDED.issue_number, state = EXCLUDED.state,
          validation = EXCLUDED.validation, pr_number = EXCLUDED.pr_number, updated_at = EXCLUDED.updated_at
        WHERE (todo_leaves.issue_number, todo_leaves.state, todo_leaves.validation, todo_leaves.pr_number)
          IS DISTINCT FROM (EXCLUDED.issue_number, EXCLUDED.state, EXCLUDED.validation, EXCLUDED.pr_number);
        RETURN NULL;
      END
      $fn$
    $create$, current_schema()); END $do$`;
    yield* sql `
    CREATE CONSTRAINT TRIGGER todo_leaves_project
    AFTER INSERT OR UPDATE OF state, issue_number, pr_number, revision OR DELETE ON todos
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW
    EXECUTE FUNCTION todo_leaves_project()`;
    yield* sql `
    INSERT INTO todo_leaves (todo_id, repo_id, number, issue_number, state, validation, pr_number, updated_at)
    SELECT id, repo_id, number, issue_number, state, 'none', pr_number, updated_at
    FROM todos WHERE issue_number IS NOT NULL`;
    yield* sql `RESET lock_timeout`;
});
